-- 247: SkillsFuture Claim / CPF Extraction / WSQ Registration visual-flow pages.
--      Footer block 1 swaps the YouTube links for the new internal pages and
--      adds an 'Extract CPF Contribution' link under Enquires.
--      Footer blocks 1 & 7 are overwritten with the clean repo version, which
--      drops the prod-only 'SUPPORT' and 'SKILL CERTIFICATIONS' columns that
--      were added directly in the prod admin (not in the local snapshot).

INSERT INTO cms_page (title, root_template, identifier, content_heading, content, is_active, sort_order, creation_time, update_time) SELECT 'How to Claim SkillsFuture Credit','one_column','how-to-claim-skillsfuture-credit.html','How to Claim SkillsFuture Credit',,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='how-to-claim-skillsfuture-credit.html') t);

INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='how-to-claim-skillsfuture-credit.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);

INSERT INTO cms_page (title, root_template, identifier, content_heading, content, is_active, sort_order, creation_time, update_time) SELECT 'How to Extract Your CPF Contribution Report','one_column','extract-cpf-contribution.html','How to Extract Your CPF Contribution Report',,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='extract-cpf-contribution.html') t);

INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='extract-cpf-contribution.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);

INSERT INTO cms_page (title, root_template, identifier, content_heading, content, is_active, sort_order, creation_time, update_time) SELECT 'How to Register a WSQ Course','one_column','how-to-register-wsq-course.html','How to Register a WSQ Course',,1,0,NOW(),NOW() FROM dual WHERE NOT EXISTS (SELECT 1 FROM (SELECT page_id FROM cms_page WHERE identifier='how-to-register-wsq-course.html') t);

INSERT INTO cms_page_store (page_id, store_id) SELECT p.page_id,0 FROM cms_page p WHERE p.identifier='how-to-register-wsq-course.html' AND NOT EXISTS (SELECT 1 FROM cms_page_store s WHERE s.page_id=p.page_id);

